import re

def parse(lines):
    recs = []
    used = []
    skip = []
    cur = None
    last = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if re.match(r'^\s*<[^>]+>', l) or re.match(r'^\s*\[[^\]]+\]', l):
            skip.append(i)
            continue
        if re.match(r'^\s{2,}\S', l) and cur is not None and last:
            if last.lower().endswith('ports'):
                v = ', '.join(s.split())
                sep = ', '
            else:
                v = s
                sep = '; '
            old = cur.get(last, '')
            cur[last] = (old + sep + v) if old and old != 'None' else v
            used.append(i)
            continue
        m = re.match(r'^\s?(?P<key>[A-Za-z][^:]*?):\s*(?P<value>.*?)\s*$', l)
        if m:
            k = m.group('key').strip()
            v = m.group('value')
            if k == 'VLAN ID' or cur is None:
                cur = {}
                recs.append(cur)
            cur[k] = v
            last = k
            used.append(i)
            continue
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    rows = []
    for r in recs:
        rows.append({k: r.get(k, '') for k in keys})
    blocks = []
    if rows:
        blocks.append({'name': 'vlans', 'kind': 'table', 'lines': used, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
